#include <iostream>
#include <vector>
#include <deque>
#include <cstring>
#include <climits>
#include <algorithm>
using namespace std;

char gridA[12][12], gridB[12][12];
int N, T;
bool memo[70][12][12][12][12];
bool canReach[12][12][12][12];
int arrivalTime[12][12];
vector<vector<int>> adjList;
int edgeCap[210][210], edgeFlow[210][210];
int nodeSupply[210], nodeLevel[210];
int nodeID[11][11];

void explore(int step, int r, int c, int origR, int origC) {
    if (T >= 70) return;
    if (r < 0 || r >= N || c < 0 || c >= N) return;
    if (gridA[r][c] < '0' || gridA[r][c] > '9') return;
    if (step > T + 1) return;
    if (memo[step][r][c][origR][origC]) return;
    if (step > arrivalTime[r][c] && arrivalTime[r][c] != 0) return;
    if (step == arrivalTime[r][c] && arrivalTime[r][c] != 0 && (gridB[r][c] > '9' || gridB[r][c] <= '0')) return;
    memo[step][r][c][origR][origC] = true;
    if (step < arrivalTime[r][c]) {
        explore(step+1, r, c, origR, origC);
        explore(step+1, r+1, c, origR, origC);
        explore(step+1, r-1, c, origR, origC);
        explore(step+1, r, c+1, origR, origC);
        explore(step+1, r, c-1, origR, origC);
    }
}

int main() {
#ifndef ONLINE_JUDGE
    freopen("1.txt", "rt", stdin);
#endif
    cin >> N >> T;
    for (int i = 0; i < N; ++i)
        for (int j = 0; j < N; ++j)
            cin >> gridA[i][j];
    for (int i = 0; i < N; ++i)
        for (int j = 0; j < N; ++j)
            cin >> gridB[i][j];

    deque<pair<int,int>> q;
    memset(arrivalTime, -1, sizeof(arrivalTime));
    for (int i = 0; i < N; ++i)
        for (int j = 0; j < N; ++j)
            if (gridA[i][j] == 'Z') {
                arrivalTime[i][j] = 0;
                q.emplace_back(i, j);
            }

    const int dr[4] = {-1, 0, 1, 0};
    const int dc[4] = {0, -1, 0, 1};
    while (!q.empty()) {
        auto [r, c] = q.front(); q.pop_front();
        if (arrivalTime[r][c] >= T) continue;
        for (int d = 0; d < 4; ++d) {
            int nr = r + dr[d], nc = c + dc[d];
            if (nr >= 0 && nr < N && nc >= 0 && nc < N &&
                gridA[nr][nc] >= '0' && gridA[nr][nc] <= '9' && arrivalTime[nr][nc] == -1) {
                arrivalTime[nr][nc] = arrivalTime[r][c] + 1;
                q.emplace_back(nr, nc);
            }
        }
    }
    for (int i = 0; i < N; ++i)
        for (int j = 0; j < N; ++j)
            if (arrivalTime[i][j] == -1) arrivalTime[i][j] = T;

    for (int i = 0; i < N; ++i)
        for (int j = 0; j < N; ++j)
            if (gridA[i][j] >= '0' && gridA[i][j] <= '9')
                explore(0, i, j, i, j);

    for (int i1 = 0; i1 < N; ++i1)
        for (int j1 = 0; j1 < N; ++j1)
            for (int i2 = 0; i2 < N; ++i2)
                for (int j2 = 0; j2 < N; ++j2)
                    for (int s = 0; s <= T; ++s)
                        canReach[i1][j1][i2][j2] |= memo[s][i1][j1][i2][j2];

    adjList.resize(1);
    for (int i1 = 0; i1 < N; ++i1)
        for (int j1 = 0; j1 < N; ++j1)
            if (gridA[i1][j1] > '0' && gridA[i1][j1] <= '9') {
                int u = adjList.size();
                adjList.emplace_back();
                nodeSupply[u] = gridA[i1][j1] - '0';
                for (int i2 = 0; i2 < N; ++i2)
                    for (int j2 = 0; j2 < N; ++j2)
                        if (gridB[i2][j2] > '0' && gridB[i2][j2] <= '9' && canReach[i2][j2][i1][j1]) {
                            int v;
                            if (nodeID[i2][j2] == 0) {
                                nodeID[i2][j2] = adjList.size();
                                adjList.emplace_back();
                            }
                            v = nodeID[i2][j2];
                            adjList[u].push_back(v);
                            adjList[v].push_back(u);
                            edgeCap[u][v] = 10000;
                            edgeCap[v][u] = 0;
                        }
            }

    for (int i2 = 0; i2 < N; ++i2)
        for (int j2 = 0; j2 < N; ++j2)
            if (gridB[i2][j2] > '0' && gridB[i2][j2] <= '9' && nodeID[i2][j2] > 0) {
                int v = nodeID[i2][j2];
                adjList[v].push_back(0);
                edgeCap[v][0] = gridB[i2][j2] - '0';
                edgeCap[0][v] = 0;
            }

    for (int i = 0; i < (int)adjList.size(); ++i) nodeLevel[i] = 0;
    nodeLevel[0] = adjList.size();

    while (true) {
        bool anyChange = false;
        for (int u = 1; u < (int)adjList.size(); ++u) {
            while (nodeSupply[u] > 0) {
                bool pushed = false;
                int minLvl = INT_MAX;
                for (int v : adjList[u]) {
                    if (edgeCap[u][v] - edgeFlow[u][v] > 0) minLvl = min(minLvl, nodeLevel[v]);
                    if (edgeCap[u][v] - edgeFlow[u][v] > 0 && nodeLevel[u] == nodeLevel[v] + 1) {
                        int delta = min(edgeCap[u][v] - edgeFlow[u][v], nodeSupply[u]);
                        edgeFlow[u][v] += delta;
                        edgeFlow[v][u] -= delta;
                        nodeSupply[u] -= delta;
                        nodeSupply[v] += delta;
                        pushed = true;
                        anyChange = true;
                        if (nodeSupply[u] == 0) goto skipNode;
                    }
                }
                if (nodeLevel[u] != minLvl + 1 && minLvl != INT_MAX) {
                    nodeLevel[u] = minLvl + 1;
                    anyChange = true;
                }
                if (!pushed) skipNode: break;
            }
        }
        if (!anyChange) break;
    }

    cout << nodeSupply[0];
    return 0;
}
